def yaml_loader_function(directories, sample, sim_hours, year, API_details, existing_path):
    def normalize_year_value(year_value):
        if isinstance(year_value, (list, tuple)) and len(year_value) == 1:
            return normalize_year_value(year_value[0])
        if isinstance(year_value, str):
            trimmed = year_value.strip().strip("\"'")
            if trimmed.startswith('[') and trimmed.endswith(']'):
                inner = trimmed[1:-1].strip()
                if ',' not in inner and inner:
                    return normalize_year_value(inner)
            return trimmed
        return year_value

    def resolve_directory_path(directories_map, year_value):
        normalized_year = normalize_year_value(year_value)
        candidates = []
        for candidate in [normalized_year, str(normalized_year)]:
            if candidate not in candidates:
                candidates.append(candidate)
        try:
            int_year = int(normalized_year)
            for candidate in [int_year, str(int_year)]:
                if candidate not in candidates:
                    candidates.append(candidate)
        except Exception:
            pass
        for candidate in candidates:
            if candidate in directories_map:
                return directories_map[candidate]
        normalized_map = {str(key).strip().strip("\"'"): value for key, value in directories_map.items()}
        normalized_key = str(normalized_year).strip().strip("\"'")
        if normalized_key in normalized_map:
            return normalized_map[normalized_key]
        raise KeyError(f'Could not resolve reliability year {year_value!r} from directories: {list(directories_map.keys())!r}')

    def can_reuse_existing_wind(existing_dir, target_data_dir):
        existing_wind_file = os.path.join(existing_dir, 'windspeed_data.csv')
        target_wind_sites = os.path.join(target_data_dir, 'Wind', 'wind_sites.csv')
        if not (os.path.exists(existing_wind_file) and os.path.exists(target_wind_sites)):
            return False
        try:
            existing_columns = list(pd.read_csv(existing_wind_file, nrows=0, index_col=0).columns)
            target_sites = pd.read_csv(target_wind_sites)['Farm Name'].astype(str).tolist()
        except Exception:
            return False
        return existing_columns == target_sites

    config_dict = {}
    config_dict['data'] = resolve_directory_path(directories, year)
    config_dict['load_factor'] = 1
    config_dict['model'] = 'Zonal'
    config_dict['samples'] = sample
    config_dict['sim_hours'] = sim_hours
    config_dict['download_s'] = 'Yes'
    config_dict['download_w'] = 'Yes'
    if isinstance(existing_path, (str, os.PathLike)) and os.path.exists(existing_path):
        solar_dir = os.path.join(config_dict['data'], 'Solar')
        wind_dir = os.path.join(config_dict['data'], 'Wind')
        os.makedirs(solar_dir, exist_ok=True)
        os.makedirs(wind_dir, exist_ok=True)
        base_solar_file = os.path.join(existing_path, 'solar_data.xlsx')
        if os.path.exists(base_solar_file):
            target_solar_file = os.path.join(solar_dir, 'solar_data.xlsx')
            shutil.copy2(base_solar_file, target_solar_file)
            config_dict['download_s'] = 'No'
        if can_reuse_existing_wind(existing_path, config_dict['data']):
            base_wind_file = os.path.join(existing_path, 'windspeed_data.csv')
            target_wind_file = os.path.join(wind_dir, 'windspeed_data.csv')
            shutil.copy2(base_wind_file, target_wind_file)
            config_dict['download_w'] = 'No'
    if config_dict['download_s'] == 'Yes' or config_dict['download_w'] == 'Yes':
        config_dict['api_key'] = API_details['api_key']
        config_dict['email'] = API_details['Email']
        config_dict['name'] = API_details['Name']
        config_dict['affiliation'] = API_details['Affiliation']
        config_dict['year_start_w'] = 2007
        config_dict['year_end_w'] = 2007
        config_dict['year_start_s'] = 2022
        config_dict['year_end_s'] = 2022
    config_dict['n_clusters'] = 8
    yaml_path = os.path.join(config_dict['data'], 'input.yaml')
    with open(yaml_path, 'w') as f:
        yaml.safe_dump(config_dict, f, sort_keys=False)
    return {'config': config_dict, 'yaml_path': yaml_path}

